# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">OLASILIK TEMEL KAVRAMLARI: DENEY, ÇIKTI, ÖRNEK UZAY VE OLAY</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Kavram Tanımları (M.8.5.1.1)</text>\n  <text x="180" y="94" text-anchor="middle" font-size="11" fill="#1e3a8a">• Deney: Sonucu merak edilen rastgele işlem</text>\n  <text x="180" y="116" text-anchor="middle" font-size="11" fill="#1e3a8a">• Çıktı: Deneyde elde edilebilecek her bir sonuç</text>\n  <text x="180" y="138" text-anchor="middle" font-size="11" fill="#1e3a8a">• Örnek Uzay (Tüm Olası Durumlar): Deneydeki</text>\n  <text x="180" y="156" text-anchor="middle" font-size="11" fill="#1e3a8a">bütün çıktıların oluşturduğu küme</text>\n  <text x="180" y="180" text-anchor="middle" font-size="11" fill="#1e3a8a">• Olay: Örnek uzayın içinden gerçekleşmesi</text>\n  <text x="180" y="198" text-anchor="middle" font-size="11" fill="#1e3a8a">istenen belirli durum (İstenen Çıktılar)</text>\n  <text x="180" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Eş Olasılıklı: Her çıktının şansı 1/n kadardır.</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Örnek: Hilesiz Bir Zarın Atılması</text>\n  <text x="520" y="96" text-anchor="middle" font-size="11" fill="#14532d">• Deney: Zarın havaya atılması</text>\n  <text x="520" y="120" text-anchor="middle" font-size="11" fill="#14532d">• Örnek Uzay: {1, 2, 3, 4, 5, 6} → n = 6 olası durum</text>\n  <text x="520" y="144" text-anchor="middle" font-size="11" fill="#14532d">• Olay: Üst yüze asal sayı gelmesi</text>\n  <text x="520" y="168" text-anchor="middle" font-size="11" fill="#14532d">• Olayın Çıktıları: {2, 3, 5} → 3 istenen durum</text>\n  <text x="520" y="196" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">Olasılık = İstenen (3) / Tüm (6) = 3/6 = 1/2</text>\n  <text x="520" y="220" text-anchor="middle" font-size="11" fill="#166534">Her bir rakamın tek tek gelme olasılığı = 1/6</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">OLASILIK DEĞER ARALIĞI: İMKÂNSIZ OLAY (0) VE KESİN OLAY (1)</text>\n  <rect x="20" y="45" width="660" height="90" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <!-- Sayı doğrusu 0 ile 1 arası -->\n  <line x1="80" y1="85" x2="620" y2="85" stroke="#854d0e" stroke-width="3"/>\n  <circle cx="80" cy="85" r="7" fill="#be123c"/>\n  <circle cx="350" cy="85" r="7" fill="#1d4ed8"/>\n  <circle cx="620" cy="85" r="7" fill="#15803d"/>\n  <text x="80" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#be123c">0 (%0)</text>\n  <text x="80" y="112" text-anchor="middle" font-size="11" font-weight="bold" fill="#be123c">İmkânsız Olay</text>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">1/2 (0,5 = %50)</text>\n  <text x="350" y="112" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Yarı Yarıya Şans</text>\n  <text x="620" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">1 (%100)</text>\n  <text x="620" y="112" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Kesin Olay</text>\n\n  <rect x="20" y="150" width="320" height="95" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="180" y="172" text-anchor="middle" font-size="12" font-weight="bold" fill="#be123c">Temel Kural: 0 ≤ P(A) ≤ 1 (M.8.5.1.4)</text>\n  <text x="180" y="194" text-anchor="middle" font-size="11" fill="#881337">• Bir olayın olma olasılığı negatif olamaz</text>\n  <text x="180" y="212" text-anchor="middle" font-size="11" fill="#881337">ve 1\'den büyük (bileşik kesir) olamaz!</text>\n  <text x="180" y="232" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">• P(Olma) + P(Olmama) = 1</text>\n\n  <rect x="360" y="150" width="320" height="95" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="520" y="172" text-anchor="middle" font-size="12" font-weight="bold" fill="#0e7490">Daha Fazla · Eşit · Daha Az Olasılıklı</text>\n  <text x="520" y="194" text-anchor="middle" font-size="11" fill="#164e63">Torbada: 5 Kırmızı, 5 Mavi, 2 Sarı top varsa;</text>\n  <text x="520" y="212" text-anchor="middle" font-size="11" fill="#164e63">• Kırmızı ve Mavi gelme olasılığı EŞİTTİR.</text>\n  <text x="520" y="232" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">• Sarı gelme olasılığı DAHA AZDIR (2 &lt; 5).</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">BASİT OLAYLARIN OLMA OLASILIĞI HESAPLAMA VE GRAFİK BAĞLANTISI</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Olasılık Hesaplama Formülü (M.8.5.1.5)</text>\n  <rect x="40" y="85" width="280" height="55" rx="6" fill="#f3e8ff" stroke="#9333ea" stroke-width="1"/>\n  <text x="180" y="106" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">İstenen Olası Durumların Sayısı</text>\n  <line x1="55" y1="114" x2="305" y2="114" stroke="#6b21a8" stroke-width="2"/>\n  <text x="180" y="132" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">Tüm Olası Durumların Sayısı (Örnek Uzay)</text>\n  <text x="180" y="168" text-anchor="middle" font-size="11" fill="#581c87">• Sonuç en sade kesir, ondalık gösterim</text>\n  <text x="180" y="186" text-anchor="middle" font-size="11" fill="#581c87">veya yüzde (%) olarak ifade edilebilir.</text>\n  <text x="180" y="214" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">Örnek: 20 kişide 5 gözlüklü → 5/20 = 1/4 = %25</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Daire Grafiği ve Olasılık İlişkisi</text>\n  <circle cx="430" cy="140" r="45" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <path d="M 430 140 L 430 95 A 45 45 0 0 1 475 140 Z" fill="#86efac" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="448" y="128" font-size="10" font-weight="bold" fill="#14532d">90°</text>\n  <text x="580" y="102" text-anchor="middle" font-size="11" fill="#14532d">Daire grafiğinde merkez</text>\n  <text x="580" y="120" text-anchor="middle" font-size="11" fill="#14532d">açısı α olan dilimden</text>\n  <text x="580" y="138" text-anchor="middle" font-size="11" fill="#14532d">seçim yapma olasılığı:</text>\n  <text x="580" y="168" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">P = α / 360°</text>\n  <text x="520" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Örnek: 90° dilim → 90/360 = 1/4 olasılık</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
